# region: sift
def sift(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: render
def render(xs, offset=-1):
    return [v + offset for v in xs]

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return emit(fold(render(intake(sift(raw)))))

